public class Main{public static void main(String[]x){String s="racecar",r="";for(int i=s.length()-1;i>=0;i--)r+=s.charAt(i);if(s.equals(r))System.out.println(s+" is a palindrome");else System.out.println(s+" is not a palindrome");}}
